"""Browser-side platform contract/fixture tests with mocked native transport; not Android/EXE runtime QA."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
BASE=os.environ.get('INDIFF_TEST_URL','http://127.0.0.1:48179');OUT=Path('qa/platform-browser');OUT.mkdir(parents=True,exist_ok=True)
fixture=(Path(__file__).parent/'fixtures/original-workflow.json').read_text();checks=[]
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 context=browser.new_context(viewport={'width':1440,'height':900},accept_downloads=True);page=context.new_page();errors=[];page.on('pageerror',lambda error:errors.append(str(error)));page.goto(BASE);page.wait_for_selector('.empty-panel')
 page.locator('#text-import').set_input_files({'name':'원본.workflow.json','mimeType':'application/json','buffer':fixture.encode()});page.wait_for_selector('.original-card');assert page.locator('.original-card').count()==4;assert 'reader' in page.locator('.original-workflow').inner_text();checks.append('original workflow JSON imports into original card inspector, not local-demo DAG')
 page.locator('[data-original-card="reader"]').click();page.locator('#edit-form [name=title]').fill('원본 카드 수정');page.locator('#edit-form button[type=submit]').click();assert '원본 카드 수정' in page.locator('.original-workflow').inner_text();checks.append('original card editing updates its JSON copy')
 page.locator('[data-original-position="reader"]').click();page.locator('#edit-form [name=x]').fill('95');page.locator('#edit-form [name=y]').fill('145');page.locator('#edit-form button[type=submit]').click()
 with page.expect_download() as download:page.locator('[data-action=export-doc]').click()
 download.value.save_as(str(OUT/'workflow-export.json'));exported=json.loads((OUT/'workflow-export.json').read_text());assert exported['layout']['reader']==[95,145];assert exported['cards'][0]['vendor_extension']=={'keep':True};assert exported['future_root']==json.loads(fixture)['future_root'];assert exported['links']==json.loads(fixture)['links'];assert exported['cards'][0]['title']=='원본 카드 수정';checks.append('export roundtrip preserves original unknown card/root/edge fields and edits')
 page.screenshot(path=str(OUT/'original-workflow-desktop.png'))
 page.locator('#text-import').set_input_files({'name':'bad.workflow.json','mimeType':'application/json','buffer':b'{"cards":[],"links":[],"x":1,"x":2}'});assert '중복 키' in page.locator('#toast').inner_text();checks.append('duplicate JSON keys rejected without silently overwriting original fields')
 page.locator('#text-import').set_input_files({'name':'original.workflow.yaml','mimeType':'text/yaml','buffer':b'cards: []'});assert 'YAML' in page.locator('#toast').inner_text();checks.append('unsupported YAML is explicitly rejected')
 mobile=browser.new_context(viewport={'width':390,'height':844},is_mobile=True);mp=mobile.new_page();mp.goto(BASE);mp.locator('#text-import').set_input_files({'name':'모바일.workflow.json','mimeType':'application/json','buffer':fixture.encode()});mp.wait_for_selector('.original-card');assert mp.evaluate('document.documentElement.scrollWidth<=innerWidth');mp.screenshot(path=str(OUT/'original-workflow-mobile.png'));checks.append('original JSON inspector remains usable at 390px')
 native=browser.new_context(viewport={'width':390,'height':844},is_mobile=True)
 native.add_init_script("""window.__nativeCalls=[];window.indiffNative={async invoke(method,payload){window.__nativeCalls.push({method,payload});if(method==='workspace.load')return {ok:true,value:{snapshot:JSON.parse(localStorage.getItem('__test_native_snapshot')||'null')}};if(method==='workspace.save'){localStorage.setItem('__test_native_snapshot',JSON.stringify(payload.snapshot));return {ok:true,value:{bytes:100}};}if(method==='file.pick')return {ok:true,value:{canceled:false,name:'native.md',text:'# Native SAF contract'}};if(method==='file.saveAs')return {ok:true,value:{canceled:false,name:payload.name,bytes:payload.text.length}};return {ok:true,value:{platform:'android',state:'disconnected',ai:false}};}};""")
 np=native.new_page();np.goto(BASE);np.wait_for_function("document.querySelector('#save-status').textContent==='앱 저장소에 저장됨'");np.locator('#sidebar-rail').click();np.locator('#import-file').click();np.wait_for_selector('[data-reader]');assert 'Native SAF contract' in np.locator('.pane.active').inner_text();np.wait_for_function("document.querySelector('#save-status').textContent==='앱 저장소에 저장됨'");np.reload();np.wait_for_selector('[data-reader]');assert 'Native SAF contract' in np.locator('.pane.active').inner_text();checks.append('mock native picker imports, atomic snapshot contract saves and reload restores documents/tabs')
 np.locator('[data-action=export-doc]').click();np.wait_for_function("window.__nativeCalls.some(c=>c.method==='file.saveAs'&&c.payload.kind==='text')");np.locator('#sidebar-rail').click();np.locator('#export-backup').click();np.wait_for_function("window.__nativeCalls.some(c=>c.method==='file.saveAs'&&c.payload.kind==='workspace')");checks.append('native text/whole-workspace export uses correct bounded OS picker capability')
 assert np.evaluate("JSON.parse(localStorage.getItem('__test_native_snapshot')).workspace.agents.every(a=>a.model==='미연결')");assert not errors,errors;browser.close()
(OUT/'result.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'pageErrors':errors,'scope':'cloud Chromium with native transport mocks; not installed Android/Windows runtime'},ensure_ascii=False,indent=2));print(json.dumps({'passed':len(checks),'checks':checks,'pageErrors':errors},ensure_ascii=False))
